/* Service worker – offline-first app shell. The asset list + version are generated by tools/update-sw.mjs */
// BEGIN GENERATED
const VERSION = 'a90350d678';
const PRECACHE = [
 "./",
 "./index.html",
 "./manifest.webmanifest",
 "./css/app.css",
 "./js/app.js",
 "./js/backend.js",
 "./js/config.js",
 "./js/data.js",
 "./js/editor/admin.js",
 "./js/editor/editor.js",
 "./js/editor/forms.js",
 "./js/editor/photo.js",
 "./js/engine/attach.js",
 "./js/engine/campus-router.js",
 "./js/engine/format.js",
 "./js/engine/geo.js",
 "./js/engine/recommend.js",
 "./js/engine/router.js",
 "./js/engine/safety.js",
 "./js/engine/steps.js",
 "./js/engine/time.js",
 "./js/engine/topo-steps.js",
 "./js/strings.he.js",
 "./js/strings.js",
 "./js/ui/indoor.js",
 "./js/ui/map.js",
 "./js/ui/walk.js",
 "./js/ui/whereami.js",
 "./js/util.js",
 "./vendor/leaflet/images/layers-2x.png",
 "./vendor/leaflet/images/layers.png",
 "./vendor/leaflet/images/marker-icon-2x.png",
 "./vendor/leaflet/images/marker-icon.png",
 "./vendor/leaflet/images/marker-shadow.png",
 "./vendor/leaflet/leaflet.css",
 "./vendor/leaflet/leaflet.js",
 "./vendor/ngraph/ngraph.graph.es.js",
 "./vendor/ngraph/ngraph.path.es.js",
 "./data/sheba.json",
 "./data/topology.json",
 "./data/clinics-directory.json",
 "./data/tests-directory.json",
 "./icons/icon-192.png",
 "./icons/icon-512.png",
 "./icons/icon-maskable-512.png",
 "./icons/icon.svg"
];
// END GENERATED

const SHELL = 'spg-shell-' + VERSION;
const TILES = 'spg-tiles-v1';
const MAX_TILES = 400;      // only tiles the user actually looked at – no bulk/prefetch (OSM tile policy)

self.addEventListener('install', e => {
  e.waitUntil(caches.open(SHELL).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('spg-shell-') && k !== SHELL) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);

  if (url.hostname === 'tile.openstreetmap.org') { e.respondWith(tile(req)); return; }
  if (url.origin !== location.origin) return;                       // Supabase, Waze… untouched

  if (req.mode === 'navigate') { e.respondWith(networkFirst(new Request('./index.html'), 3000)); return; }
  if (url.pathname.endsWith('/data/sheba.json')) { e.respondWith(networkFirst(req, 4000)); return; }
  e.respondWith(staleWhileRevalidate(req));
});

async function networkFirst(req, timeoutMs) {
  const cache = await caches.open(SHELL);
  try {
    const res = await Promise.race([fetch(req), new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), timeoutMs))]);
    if (res.ok) cache.put(req, res.clone());
    return res;
  } catch {
    return (await cache.match(req, { ignoreSearch: true })) || (await cache.match('./index.html')) || Response.error();
  }
}

async function staleWhileRevalidate(req) {
  const cache = await caches.open(SHELL);
  const hit = await cache.match(req, { ignoreSearch: true });
  const net = fetch(req).then(res => { if (res.ok) cache.put(req, res.clone()); return res; }).catch(() => null);
  return hit || (await net) || Response.error();
}

async function tile(req) {
  const cache = await caches.open(TILES);
  const hit = await cache.match(req);
  if (hit) return hit;
  try {
    const res = await fetch(req);
    if (res.ok) {
      cache.put(req, res.clone());
      const keys = await cache.keys();
      if (keys.length > MAX_TILES) for (const k of keys.slice(0, keys.length - MAX_TILES)) await cache.delete(k);
    }
    return res;
  } catch {
    return Response.error();      // offline & never viewed: the map still shows our own building outlines
  }
}
